"""Apply explicit typographical spacing corrections to authored prose only.

No source quotations, locators, identifiers, verdicts or mathematical decisions
are generated by this program. The mapping is deliberately explicit.
"""
import ast,json,re,csv
from pathlib import Path
B=Path(__file__).resolve().parents[1]
tree=ast.parse((B/'programs'/'build_claims_extra.py').read_text())
spacing={}
for node in tree.body:
 if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='spacing' for t in node.targets):spacing=ast.literal_eval(node.value)
spacing.update({
'ofQ':'of Q','insideC':'inside C','intoC':'into C','andC-pointsets':'and C-point sets','Q̄-pointsets':'Q̄-point sets','pointsets':'point sets','fixedembedding':'fixed embedding','givenembedding':'given embedding',
'degreeN':'degree N','isolated6N':'isolated 6N','meaningof6N':'meaning of 6N','notidentifiable':'not identifiable','degreecount':'degree count','thedegree':'the degree','Degreeequalities':'Degree equalities','commondegree':'common degree','thesame':'the same',
'definingdraft':'defining draft','permutationentry':'permutation entry','cancelledtrial':'cancelled trial','leftblank':'left blank','algebraicmismatch':'algebraic mismatch','headingarithmeticallyinconsistent':'heading arithmetically inconsistent','asof':'as of','as of2026':'as of 2026','unresolved2026':'unresolved 2026','formulated2026':'formulated 2026','counterexample2026':'counterexample 2026','proof2026':'proof 2026','Background1971':'Background 1971','background1971':'background 1971',
'fromSGA1':'from SGA 1','beforeMP':'before MP','afterMP':'after MP','withMP':'with MP','inCL':'in CL','toCL':'to CL','claim063':'claim 063','claim057':'claim 057','claim076':'claim 076','invariant-rigidification':'invariant rigidification','map-isotopy':'map-isotopy',
'is T̂':'is T̂','inΓ':'in Γ','becauseT̂':'because T̂','the literalν':'the literal ν','a3-cycle':'a 3-cycle','the1993':'the 1993','the1992':'the 1992','torusC2':'torus C2','as a3':'as a 3','inS3':'in S3','ofS3':'of S3','kernelC2':'kernel C2','groupC2':'group C2','groupS3':'group S3','groupS6':'group S6','theχ3':'the χ3','confirmsS6':'confirms S6','arithmeticS3':'arithmetic S3','withS3':'with S3','andS3':'and S3','theS3':'the S3','isS3':'is S3','theS6':'the S6','monodromyS6':'monodromy S6','full groupC2':'full group C2',
'ofP(c)':'of P(c)','ofδ(c)':'of δ(c)','withP':'with P','Keepδ':'Keep δ','Theδ':'The δ','a degree6':'a degree 6','specificdegree':'specific degree','degree10':'degree ten','degree5':'degree five','degree6':'degree six',
'for everyφ':'for every φ','everyφ':'every φ','everyt':'every t','forφ':'for φ','specialφ':'special φ','conditionφ':'condition φ','requiresφ':'requires φ','from≤2':'from ≤2','andφ':'and φ','Ifφ':'If φ','thenφ':'then φ','φ(1)=1⇒':'φ(1)=1 ⇒ ','maps0,∞':'maps 0,∞','send1':'send 1','old1':'old 1','over1':'over 1','over0':'over 0','at1':'at 1','at0':'at 0','index1':'index 1','index2':'index 2','index3':'index 3','exactly2':'exactly 2','is2':'is 2',
'displayedI':'displayed I','areI,II,III':'are I,II,III','eliminateI,II,III':'eliminate I,II,III','eliminateII,III':'eliminate II,III','notI':'not I','ofordern':'of order n','modelsF_n':'models F_n','Conditionsa,b,c':'Conditions a,b,c','with≤4':'with ≤4','from115':'from 115','on119':'on 119','on130':'on 130','on132':'on 132','on112':'on 112','in129':'in 129','in126':'in 126',
'setsS,A,F':'sets S,A,F','ofX':'of X','onX':'on X','whileX':'while X','off⁻¹':'of f⁻¹','offinite':'of finite','off':'off','graphA':'graph A','graphC':'graph C','thatC':'that C','AssumeA':'Assume A','assumingA':'assuming A','requireA':'require A','becauseA':'because A','thenf':'then f','takingf':'taking f','Forf':'For f','everyf':'every f','functionf':'function f','functionφ':'function φ','indexe':'index e','degreee':'degree e','pointb':'point b','pointsb':'points b','ofB':'of B','ofS²':'of S²','onS²':'on S²',
'eachface':'each face','faceboundary':'face boundary','finitetype':'finite type','withfinite':'with finite','isotopykernel':'isotopy kernel','familyclaims':'family claims','mapautomorphism':'map automorphism','centralizergroup':'centralizer group','fromscan':'from scan','scan89':'scan 89','scan90':'scan 90','scan106':'scan 106','scans89':'scans 89','scans90':'scans 90',
'proofP1':'proof P1','proofP2':'proof P2','proofP3':'proof P3','proofP4':'proof P4','coprimeP':'coprime P','exactformula':'exact formula','fullPDF':'full PDF','authorPDF':'author PDF','preprint2013':'preprint 2013','circulation2000':'circulation 2000','publication2002':'publication 2002',
})
def polish(s):
 for old,new in spacing.items():s=s.replace(old,new)
 s=re.sub(r'\b(Theorem|Theorems|Proposition|Example|Figure|Definition|Corollary|Lemma|printed|circulation|publication|preprint|spring|copyright|before|account|journal|audit|scan|scans|line|lines|rank|order|degree|at|in|by|of|and|after|since)(?=\d)',r'\1 ',s)
 return s
for name,fields in [
 ('items.json',['statement','reconstruction','check_reason']),
 ('claims.json',['statement','status_on_pages','computation','fate','fate_date','present_status']),
 ('problems.json',['title','as_he_states','plausible_today','state_of_art','why_open','worth'])]:
 data=json.loads((B/name).read_text())
 for x in data:
  for key in fields:x[key]=polish(x[key])
 (B/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
for name,fields in [('entries.tsv',['reason']),('readings.tsv',['alternative','evidence'])]:
 with (B/name).open() as f:r=csv.DictReader(f,delimiter='\t');keys=r.fieldnames;data=list(r)
 for x in data:
  for key in fields:x[key]=polish(x[key])
 with (B/name).open('w') as f:w=csv.DictWriter(f,fieldnames=keys,delimiter='\t');w.writeheader();w.writerows(data)
print('Explicit typographical spacing applied to authored prose; source quotations and evidence locators unchanged.')
